CREATE OR REPLACE view DBP_MSI_VIEW_WWC.MV_IMS_MAMO_WUP_MO_SUM as
   SELECT
   v01.mandant_id, v01.wup_id, v01.nb_id, v04.wup_standort, v06.dat_massnahme_von AS start_bu, v06.dat_massnahme_bis AS eroeffnung, v01.kjmo, v01.zaehler_monat, v02.qualifier_id, v05. qualifier_bez, SUM(v01.umsatz_netto_kum) AS Umsatz_netto_kum, SUM(v01.umsatz_netto_vp_kum) AS Umsatz_netto_kum_VJ, CASE WHEN SUM(v01.umsatz_netto_vp_kum) <> 0 THEN TRUNC( (SUM(v01.umsatz_netto_kum) - SUM(v01.umsatz_netto_vp_kum)) / SUM(v01.umsatz_netto_vp_kum)) * 100 ELSE NULL END AS Umsatz_netto_kum_DeltaVJ, SUM(v03.umsatz_netto_kum) AS Umsatz_netto_ref_kum, SUM(v03.umsatz_netto_vp_kum) AS Umsatz_netto_ref_kum_VJ, CASE WHEN SUM(v03.umsatz_netto_vp_kum) <> 0 THEN TRUNC( (SUM(v03.umsatz_netto_kum) - SUM(v03.umsatz_netto_vp_kum)) / SUM(v03.umsatz_netto_vp_kum)) * 100 ELSE NULL END AS Umsatz_netto_ref_kum_DeltaVJ, umsatz_netto_kum_DeltaVJ - umsatz_netto_ref_kum_DeltaVJ AS Umsatz_netto_kum_DeltaVJ_DeltaRef, SUM(v01.umsatz_netto_sa_kum) AS Umsatz_netto_sa_kum, SUM(v01.umsatz_netto_sa_vp_kum) AS Umsatz_netto_sa_kum_VJ, CASE WHEN SUM(v01.umsatz_netto_sa_vp_kum) <> 0 THEN TRUNC( (SUM(v01.umsatz_netto_sa_kum) - SUM(v01.umsatz_netto_sa_vp_kum)) / SUM(v01.umsatz_netto_sa_vp_kum)) * 100 ELSE NULL END AS Umsatz_netto_sa_kum_DeltaVJ, SUM(v03.umsatz_netto_sa_kum) AS Umsatz_netto_sa_ref_kum, SUM(v03.umsatz_netto_sa_vp_kum) AS Umsatz_netto_sa_ref_kum_VJ, CASE WHEN SUM(v03.umsatz_netto_sa_vp_kum) <> 0 THEN TRUNC( (SUM(v03.umsatz_netto_sa_kum) - SUM(v03.umsatz_netto_sa_vp_kum)) / SUM(v03.umsatz_netto_sa_vp_kum)) * 100 ELSE NULL END AS Umsatz_netto_sa_ref_kum_DeltaVJ, Umsatz_netto_sa_kum_DeltaVJ - Umsatz_netto_sa_ref_kum_DeltaVJ AS Umsatz_netto_sa_kum_DeltaVJ_DeltaRef, MAX(v01.bonanzahl_sug_kum) AS Kunden_anzahl_kum, MAX(v01.bonanzahl_sug_vp_kum) AS Kunden_anzahl_kum_VJ, CASE WHEN MAX(v01.bonanzahl_sug_vp_kum) <> 0 THEN TRUNC( (MAX(v01.bonanzahl_sug_kum) - MAX(v01.bonanzahl_sug_vp_kum)) / MAX(v01.bonanzahl_sug_vp_kum)) * 100 ELSE NULL END AS Kunden_anzahl_kum_DeltaVJ, MAX(v03.bonanzahl_sug_kum) AS Kunden_anzahl_ref_kum, MAX(v03.bonanzahl_sug_vp_kum) AS Kunden_anzahl_ref_kum_VJ, CASE WHEN MAX(v03.bonanzahl_sug_vp_kum) <> 0 THEN TRUNC( (MAX(v03.bonanzahl_sug_kum) - MAX(v03.bonanzahl_sug_vp_kum)) / MAX(v03.bonanzahl_sug_vp_kum)) * 100 ELSE NULL END AS Kunden_anzahl_ref_kum_DeltaVJ, Kunden_anzahl_kum_DeltaVJ - Kunden_anzahl_ref_kum_DeltaVJ AS Kunden_anzahl_kum_DeltaVJ_DeltaRef, MAX(v01.vis_umsatz_netto_kum) AS VIS_umsatz_netto_kum, MAX(v01.vis_umsatz_netto_vp_kum) AS VIS_umsatz_netto_kum_VJ, CASE WHEN MAX(v01.vis_umsatz_netto_vp_kum) <> 0 THEN TRUNC( (MAX(v01.vis_umsatz_netto_kum) - MAX(v01.vis_umsatz_netto_vp_kum)) / MAX(v01.vis_umsatz_netto_vp_kum)) * 100 ELSE NULL END AS VIS_Umsatz_netto_kum_DeltaVJ, MAX(v03.vis_umsatz_netto_kum) AS VIS_umsatz_netto_ref_kum, MAX(v03.vis_umsatz_netto_vp_kum) AS VIS_umsatz_netto_ref_kum_VJ, CASE WHEN MAX(v03.vis_umsatz_netto_vp_kum) <> 0 THEN TRUNC( (MAX(v03.vis_umsatz_netto_kum) - MAX(v03.vis_umsatz_netto_vp_kum)) / MAX(v03.vis_umsatz_netto_vp_kum)) * 100 ELSE NULL END AS VIS_Umsatz_netto_ref_kum_DeltaVJ, VIS_Umsatz_netto_kum_DeltaVJ - VIS_Umsatz_netto_ref_kum_DeltaVJ AS VIS_Umsatz_netto_kum_DeltaVJ_DeltaRef, MAX(v01.vis_netto_stunden_kum) AS Nettostunden_kum, MAX(v01.vis_netto_stunden_vp_kum) AS Nettostunden_kum_VJ, CASE WHEN MAX(v01.vis_netto_stunden_vp_kum) <> 0 THEN TRUNC( (MAX(v01.vis_netto_stunden_kum) - MAX(v01.vis_netto_stunden_vp_kum)) / MAX(v01.vis_netto_stunden_vp_kum)) * 100 ELSE NULL END AS Nettostunden_kum_DeltaVJ, MAX(v03.vis_netto_stunden_kum) AS Nettostunden_ref_kum, MAX(v03.vis_netto_stunden_vp_kum) AS Nettostunden_ref_kum_VJ, CASE WHEN MAX(v03.vis_netto_stunden_vp_kum) <> 0 THEN TRUNC( (MAX(v03.vis_netto_stunden_kum) - MAX(v03.vis_netto_stunden_vp_kum)) / MAX(v03.vis_netto_stunden_vp_kum)) * 100 ELSE NULL END AS Nettostunden_ref_kum_DeltaVJ, Nettostunden_kum_DeltaVJ - Nettostunden_ref_kum_DeltaVJ AS Nettostunden_kum_DeltaVJ_DeltaRef, CASE WHEN MAX(v01.vis_netto_stunden_kum) <> 0 THEN TRUNC( MAX(v01.vis_umsatz_netto_kum) / MAX(v01.vis_netto_stunden_kum)) ELSE NULL END AS Nettoleistung_kum, CASE WHEN MAX(v01.vis_netto_stunden_vp_kum) <> 0 THEN TRUNC( MAX(v01.vis_umsatz_netto_vp_kum) / MAX(v01.vis_netto_stunden_vp_kum)) ELSE NULL END AS Nettoleistung_kum_VJ, CASE WHEN Nettoleistung_kum_VJ <> 0 THEN TRUNC( (Nettoleistung_kum - Nettoleistung_kum_VJ) / Nettoleistung_kum_VJ) * 100 ELSE NULL END AS Nettoleistung_kum_DeltaVJ, CASE WHEN MAX(v03.vis_netto_stunden_kum) <> 0 THEN TRUNC( MAX(v03.vis_umsatz_netto_kum) / MAX(v03.vis_netto_stunden_kum)) ELSE NULL END AS Nettoleistung_ref_kum, CASE WHEN MAX(v03.vis_netto_stunden_vp_kum) <> 0 THEN TRUNC( MAX(v03.vis_umsatz_netto_vp_kum) / MAX(v03.vis_netto_stunden_vp_kum)) ELSE NULL END AS Nettoleistung_ref_kum_VJ, CASE WHEN Nettoleistung_ref_kum_VJ <> 0 THEN TRUNC( (Nettoleistung_ref_kum - Nettoleistung_ref_kum_VJ) / Nettoleistung_ref_kum_VJ) * 100 ELSE NULL END AS Nettoleistung_ref_kum_DeltaVJ, Nettoleistung_kum_DeltaVJ - Nettoleistung_ref_kum_DeltaVJ AS Nettoleistung_kum_DeltaVJ_DeltaRef, SUM(v01.umsatz_netto_kum) - SUM(v01.ek_mep_kum) AS Ertrag_kum, SUM(v01.umsatz_netto_vp_kum) - SUM(v01.ek_mep_vp_kum) AS Ertrag_kum_VJ, CASE WHEN Ertrag_kum_VJ <> 0 THEN TRUNC( (Ertrag_kum - Ertrag_kum_VJ) / Ertrag_kum_VJ) * 100 ELSE NULL END AS Ertrag_kum_DeltaVJ, SUM(v03.umsatz_netto_kum) - SUM(v03.ek_mep_kum) AS Ertrag_kum_ref, SUM(v03.umsatz_netto_vp_kum) - SUM(v03.ek_mep_vp_kum) AS Ertrag_kum_ref_VJ, CASE WHEN Ertrag_kum_ref_VJ <> 0 THEN TRUNC( (Ertrag_kum_ref - Ertrag_kum_ref_VJ) / Ertrag_kum_ref_VJ) * 100 ELSE NULL END AS Ertrag_kum_ref_DeltaVJ, Ertrag_kum_DeltaVJ - Ertrag_kum_ref_DeltaVJ AS Ertrag_kum_DeltaVJ_DeltaRef, CASE WHEN SUM(v01.umsatz_netto_kum) <> 0 THEN TRUNC( (SUM(v01.umsatz_netto_kum) - SUM(v01.ek_mep_kum)) / SUM(v01.umsatz_netto_kum)) ELSE NULL END AS mep_spanne_kum, CASE WHEN SUM(v01.umsatz_netto_vp_kum) <> 0 THEN TRUNC( (SUM(v01.umsatz_netto_vp_kum) - SUM(v01.ek_mep_vp_kum)) / SUM(v01.umsatz_netto_vp_kum)) ELSE NULL END AS mep_spanne_kum_VJ, mep_spanne_kum - mep_spanne_kum_VJ AS mep_spanne_kum_DeltaVJ, CASE WHEN SUM(v03.umsatz_netto_kum) <> 0 THEN TRUNC( (SUM(v03.umsatz_netto_kum) - SUM(v03.ek_mep_kum)) / SUM(v03.umsatz_netto_kum)) ELSE NULL END AS mep_spanne_ref_kum, CASE WHEN SUM(v03.umsatz_netto_vp_kum) <> 0 THEN TRUNC( (SUM(v03.umsatz_netto_vp_kum) - SUM(v03.ek_mep_vp_kum)) / SUM(v03.umsatz_netto_vp_kum)) ELSE NULL END AS mep_spanne_ref_kum_VJ, mep_spanne_ref_kum - mep_spanne_ref_kum_VJ AS mep_spanne_ref_kum_DeltaVJ, mep_spanne_kum_DeltaVJ - mep_spanne_ref_kum_DeltaVJ AS mep_spanne_kum_DeltaVJ_DeltaRef, SUM(v01.umsatz_netto) AS Umsatz_netto, SUM(v01.umsatz_netto_vp) AS Umsatz_netto_VJ, CASE WHEN SUM(v01.umsatz_netto_vp) <> 0 THEN TRUNC( (SUM(v01.umsatz_netto) - SUM(v01.umsatz_netto_vp)) / SUM(v01.umsatz_netto_vp)) * 100 ELSE NULL END AS Umsatz_netto_DeltaVJ, SUM(v03.umsatz_netto) AS Umsatz_netto_ref, SUM(v03.umsatz_netto_vp) AS Umsatz_netto_ref_VJ, CASE WHEN SUM(v03.umsatz_netto_vp) <> 0 THEN TRUNC( (SUM(v03.umsatz_netto) - SUM(v03.umsatz_netto_vp)) / SUM(v03.umsatz_netto_vp)) * 100 ELSE NULL END AS Umsatz_netto_ref_DeltaVJ, Umsatz_netto_DeltaVJ - Umsatz_netto_ref_DeltaVJ AS Umsatz_netto_DeltaVJ_DeltaRef, SUM(v01.umsatz_netto_sa) AS Umsatz_netto_sa, SUM(v01.umsatz_netto_sa_vp) AS Umsatz_netto_sa_VJ, CASE WHEN SUM(v01.umsatz_netto_sa_vp) <> 0 THEN TRUNC( (SUM(v01.umsatz_netto_sa) - SUM(v01.umsatz_netto_sa_vp)) / SUM(v01.umsatz_netto_sa_vp)) * 100 ELSE NULL END AS Umsatz_netto_sa_DeltaVJ, SUM(v03.umsatz_netto_sa) AS Umsatz_netto_sa_ref, SUM(v03.umsatz_netto_sa_vp) AS Umsatz_netto_sa_ref_VJ, CASE WHEN SUM(v03.umsatz_netto_sa_vp) <> 0 THEN TRUNC( (SUM(v03.umsatz_netto_sa) - SUM(v03.umsatz_netto_sa_vp)) / SUM(v03.umsatz_netto_sa_vp)) * 100 ELSE NULL END AS Umsatz_netto_sa_ref_DeltaVJ, Umsatz_netto_sa_DeltaVJ - Umsatz_netto_sa_ref_DeltaVJ AS Umsatz_netto_sa_DeltaVJ_DeltaRef, MAX(v01.bonanzahl_sug) AS Kunden_anzahl, MAX(v01.bonanzahl_sug_vp) AS Kunden_anzahl_VJ, CASE WHEN MAX(v01.bonanzahl_sug_vp) <> 0 THEN TRUNC( (MAX(v01.bonanzahl_sug) - MAX(v01.bonanzahl_sug_vp)) / MAX(v01.bonanzahl_sug_vp)) * 100 ELSE NULL END AS Kunden_anzahl_DeltaVJ, MAX(v03.bonanzahl_sug) AS Kunden_anzahl_ref, MAX(v03.bonanzahl_sug_vp) AS Kunden_anzahl_ref_VJ, CASE WHEN MAX(v03.bonanzahl_sug_vp) <> 0 THEN TRUNC( (MAX(v03.bonanzahl_sug) - MAX(v03.bonanzahl_sug_vp)) / MAX(v03.bonanzahl_sug_vp)) * 100 ELSE NULL END AS Kunden_anzahl_ref_DeltaVJ, Kunden_anzahl_DeltaVJ - Kunden_anzahl_ref_DeltaVJ AS Kunden_anzahl_DeltaVJ_DeltaRef, MAX(v01.vis_umsatz_netto) AS VIS_Umsatz_netto, MAX(v01.vis_umsatz_netto_vp) AS VIS_Umsatz_netto_VJ, CASE WHEN MAX(v01.vis_umsatz_netto_vp) <> 0 THEN TRUNC( (MAX(v01.vis_umsatz_netto) - MAX(v01.vis_umsatz_netto_vp)) / MAX(v01.vis_umsatz_netto_vp)) * 100 ELSE NULL END AS VIS_Umsatz_netto_DeltaVJ, MAX(v03.vis_umsatz_netto) AS VIS_Umsatz_netto_ref, MAX(v03.vis_umsatz_netto_vp) AS VIS_Umsatz_netto_ref_VJ, CASE WHEN MAX(v03.vis_umsatz_netto_vp) <> 0 THEN TRUNC( (MAX(v03.vis_umsatz_netto) - MAX(v03.vis_umsatz_netto_vp)) / MAX(v03.vis_umsatz_netto_vp)) * 100 ELSE NULL END AS VIS_Umsatz_netto_ref_DeltaVJ, VIS_Umsatz_netto_DeltaVJ - VIS_Umsatz_netto_ref_DeltaVJ AS VIS_Umsatz_netto_DeltaVJ_DeltaRef, MAX(v01.vis_netto_stunden) AS Nettostunden, MAX(v01.vis_netto_stunden_vp) AS Nettostunden_VJ, CASE WHEN Nettostunden_VJ <> 0 THEN TRUNC( (Nettostunden - Nettostunden_VJ) / Nettostunden_VJ) * 100 ELSE NULL END AS Nettostunden_DeltaVJ, MAX(v03.vis_netto_stunden) AS Nettostunden_ref, MAX(v03.vis_netto_stunden_vp_kum) AS Nettostunden_ref_VJ, CASE WHEN Nettostunden_ref_VJ <> 0 THEN TRUNC( (Nettostunden_ref - Nettostunden_ref_VJ) / Nettostunden_ref_VJ) * 100 ELSE NULL END AS Nettostunden_ref_DeltaVJ, Nettostunden_DeltaVJ - Nettostunden_ref_DeltaVJ AS Nettostunden_DeltaVJ_DeltaRef, CASE WHEN MAX(v01.vis_netto_stunden) <> 0 THEN TRUNC( MAX(v01.vis_umsatz_netto) / MAX(v01.vis_netto_stunden)) ELSE NULL END AS Nettoleistung, CASE WHEN MAX(v01.vis_netto_stunden_vp) <> 0 THEN TRUNC( MAX(v01.vis_umsatz_netto_vp) / MAX(v01.vis_netto_stunden_vp)) ELSE NULL END AS Nettoleistung_VJ, CASE WHEN Nettoleistung_VJ <> 0 THEN TRUNC( (Nettoleistung - Nettoleistung_VJ) / Nettoleistung_VJ) * 100 ELSE NULL END AS Nettoleistung_DeltaVJ, CASE WHEN MAX(v03.vis_netto_stunden) <> 0 THEN TRUNC( MAX(v03.vis_umsatz_netto) / MAX(v03.vis_netto_stunden)) ELSE NULL END AS Nettoleistung_ref, CASE WHEN MAX(v03.vis_netto_stunden_vp) <> 0 THEN TRUNC( MAX(v03.vis_umsatz_netto_vp) / MAX(v03.vis_netto_stunden_vp)) ELSE NULL END AS Nettoleistung_ref_VJ, CASE WHEN Nettoleistung_ref_VJ <> 0 THEN TRUNC( (Nettoleistung_ref - Nettoleistung_ref_VJ) / Nettoleistung_ref_VJ) * 100 ELSE NULL END AS Nettoleistung_ref_DeltaVJ, Nettoleistung_DeltaVJ - Nettoleistung_ref_DeltaVJ AS Nettoleistung_DeltaVJ_DeltaRef, SUM(v01.umsatz_netto) - SUM(v01.ek_mep) AS Ertrag, SUM(v01.umsatz_netto_vp) - SUM(v01.ek_mep_vp) AS Ertrag_VJ, CASE WHEN Ertrag_VJ <> 0 THEN TRUNC( (Ertrag - Ertrag_VJ) / Ertrag_VJ) * 100 ELSE NULL END AS Ertrag_DeltaVJ, SUM(v03.umsatz_netto) - SUM(v03.ek_mep) AS Ertrag_ref, SUM(v03.umsatz_netto_vp) - SUM(v03.ek_mep_vp) AS Ertrag_ref_VJ, CASE WHEN Ertrag_ref_VJ <> 0 THEN TRUNC( (Ertrag_ref - Ertrag_ref_VJ) / Ertrag_ref_VJ) * 100 ELSE NULL END AS Ertrag_ref_DeltaVJ, Ertrag_DeltaVJ - Ertrag_ref_DeltaVJ AS Ertrag_DeltaVJ_DeltaRef, CASE WHEN SUM(v01.umsatz_netto) <> 0 THEN TRUNC( (SUM(v01.umsatz_netto) - SUM(v01.ek_mep)) / SUM(v01.umsatz_netto)) ELSE NULL END AS mep_spanne, CASE WHEN SUM(v01.umsatz_netto_vp) <> 0 THEN TRUNC( (SUM(v01.umsatz_netto_vp) - SUM(v01.ek_mep_vp)) / SUM(v01.umsatz_netto_vp)) ELSE NULL END AS mep_spanne_VJ, mep_spanne - mep_spanne_VJ AS mep_spanne_DeltaVJ, CASE WHEN SUM(v03.umsatz_netto) <> 0 THEN TRUNC(  (SUM(v03.umsatz_netto) - SUM(v03.ek_mep)) / SUM(v03.umsatz_netto)) ELSE NULL END AS mep_spanne_ref, CASE WHEN SUM(v03.umsatz_netto_vp) <> 0 THEN TRUNC( (SUM(v03.umsatz_netto_vp) - SUM(v03.ek_mep_vp)) / SUM(v03.umsatz_netto_vp)) ELSE NULL END AS mep_spanne_ref_VJ, mep_spanne_ref - mep_spanne_ref_VJ AS mep_spanne_ref_DeltaVJ, mep_spanne_DeltaVJ - mep_spanne_ref_DeltaVJ AS mep_spanne_DeltaVJ_DeltaRef

   FROM dbp_view.v_ims_mamo_wup_mo_sum v01
   INNER JOIN dbp_view.v_ims_mamo_wup_qualifier_zu v02
   ON v01.mandant_id = v02.mandant_id
   AND v01.wup_id = v02.wup_id
   AND v01.nb_id = v02.nb_id
   INNER JOIN dbp_view.v_ims_mamo_wup_qualifier_mo_sum v03
   ON v01.mandant_id = v03.mandant_id
   AND v01.wup_id = v03.wup_id
   AND v01.nb_id = v03.nb_id
   AND v01.kjmo = v03.kjmo
   AND v01.hwg_id = v03.hwg_id
   INNER JOIN dbp_view.v_wup v04
   ON v01.mandant_id = v04.mandant_id
   AND v01.wup_id = v04.wup_id
   AND v01.nb_id = v04.nb_id
   INNER JOIN dbp_view.v_ims_mamo_qualifier v05
   ON v02.mandant_id = v05.mandant_id
   AND v02.qualifier_id = v05.qualifier_id
   INNER JOIN dbp_view.v_ims_mamo_wup_massnahme_per v06
   ON v01.mandant_id = v06.mandant_id
   AND v01.wup_id = v06.wup_id
   AND v01.nb_id = v06.nb_id
   AND v06.modernisierung_art = 'MM'

   GROUP BY v01.mandant_id
   ,v01.wup_id
   ,v01.nb_id
   ,v04.wup_standort
   ,v06.dat_massnahme_von
   ,v06.dat_massnahme_bis
   ,v01.kjmo
   ,v01.zaehler_monat
   --,v01.hwg_id
   ,v02.qualifier_id
   ,v05. qualifier_bez;